//! Generated verifier-side relation messages for the neutral two-point probe.
//!
//! Each blob is laid out as initial lane claims, four rounds of lane-major
//! degree-6 polynomials, then four terminal coefficients. Hex is decoded at
//! compile time, so the SBF path reads canonical bytes from rodata and does
//! no prover-side polynomial construction.

const fn nibble(byte: u8) -> u8 {
    match byte {
        b'0'..=b'9' => byte - b'0',
        b'a'..=b'f' => byte - b'a' + 10,
        _ => panic!("invalid generated hex"),
    }
}

const fn decode_hex<const N: usize>(hex: &str) -> [u8; N] {
    let input = hex.as_bytes();
    assert!(input.len() == N * 2, "generated fixture length mismatch");
    let mut output = [0u8; N];
    let mut index = 0;
    while index < N {
        output[index] = (nibble(input[index * 2]) << 4) | nibble(input[index * 2 + 1]);
        index += 1;
    }
    output
}

pub(crate) const ONE_POINT_BASELINE: [u8; 528] = decode_hex(
    "",
);

pub(crate) const FRESH_KAPPA_SINGLE_LANE: [u8; 528] = decode_hex(
    "",
);

pub(crate) const TWO_INDEPENDENT_RELATION_LANES: [u8; 992] = decode_hex(
    "",
);

pub(crate) const DISJOINT_GAMMA51_SINGLE_LANE: [u8; 528] = decode_hex(
    "",
);
